def promote_to_golden(trace, human_label, golden_set):
    # a production failure becomes a permanent offline test
    golden_set.append({
        "input": trace["input"],
        "gold": human_label,          # verified correct answer/behavior
        "source": "online-2026-07",   # provenance for auditing
    })
    return len(golden_set)

