def implicit_score(events):
    s = 1.0
    if events.get("user_edited_answer"): s -= 0.4
    if events.get("retried_same_query"): s -= 0.3
    if events.get("escalated_to_human"): s -= 0.5
    return max(0.0, min(1.0, s))

def trace_score(trace):
    # prefer explicit feedback; fall back to implicit behavior
    if trace.get("thumbs") is not None:
        return 1.0 if trace["thumbs"] == 1 else 0.0
    return implicit_score(trace.get("events", {}))

with_thumb = {"thumbs": -1, "events": {"copied_output": True}}
no_thumb = {"thumbs": None, "events": {"retried_same_query": True}}
print("explicit:", trace_score(with_thumb))
print("implicit:", round(trace_score(no_thumb), 2))
